#!/usr/bin/env node
/**
 * The packaging half of `nish-release.yml`, the reusable release workflow for
 * a Nish program. Plain Node with no dependencies, so the workflow can run it
 * on any runner straight from the checkout.
 *
 *   release.mjs rows <targets-json>
 *     The build matrix: one row per asset, with the runner that builds it.
 *   release.mjs platform <stage-dir> <asset> <version>
 *     Write the package.json that turns a staged release directory into the
 *     npm package holding that platform's binary.
 *   release.mjs main <out-dir> <bin> <version> <asset>...
 *     Pack the repository's own package for npm, with a launcher for <bin>
 *     and an optionalDependencies pin per platform package. Prints its path.
 *
 * The npm layout is the esbuild pattern, as nish itself ships: the main
 * package names one `<name>-<asset>` package per platform as an optional
 * dependency, each declares `os` and `cpu`, and npm installs only the one that
 * matches the machine. The main package's launcher finds it and runs it.
 */
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * Every platform this workflow can build. `asset` is the target triple with
 * the vendor and ABI dropped, the spelling nish's own release assets use.
 * `host` is `uname -s`-`uname -m` on the runner, which the build job checks
 * before it labels a binary with the asset.
 */
const TARGETS = {
  "x86_64-linux": {
    runner: "ubuntu-24.04",
    host: "Linux-x86_64",
    os: "linux",
    cpu: "x64",
  },
  "aarch64-linux": {
    runner: "ubuntu-24.04-arm",
    host: "Linux-aarch64",
    os: "linux",
    cpu: "arm64",
  },
  "aarch64-darwin": {
    runner: "macos-15",
    host: "Darwin-arm64",
    os: "darwin",
    cpu: "arm64",
  },
  "x86_64-darwin": {
    runner: "macos-15-intel",
    host: "Darwin-x86_64",
    os: "darwin",
    cpu: "x64",
  },
};

const fail = (message) => {
  console.error(`release.mjs: ${message}`);
  process.exit(1);
};

const readJson = (file) => JSON.parse(fs.readFileSync(file, "utf8"));

const writeJson = (file, value) =>
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);

const run = (command, args, options = {}) => {
  const result = spawnSync(command, args, { encoding: "utf8", ...options });
  if (result.status !== 0) {
    process.stderr.write(result.stderr ?? "");
    fail(`${command} ${args.join(" ")} exited ${result.status}`);
  }
  return result.stdout;
};

/** `npm pack <dir>` into <out>, returning the path of the tarball it wrote. */
const npmPack = (dir, out) => {
  const json = run("npm", [
    "pack",
    dir,
    "--pack-destination",
    out,
    "--ignore-scripts",
    "--json",
  ]);
  return path.join(out, JSON.parse(json)[0].filename);
};

const rows = (targetsJson) => {
  let assets;
  try {
    assets = JSON.parse(targetsJson);
  } catch {
    fail(`targets is not JSON: ${targetsJson}`);
  }
  if (!Array.isArray(assets) || assets.length === 0) {
    fail("targets must be a non-empty JSON array of assets");
  }
  const unknown = assets.filter((a) => !(a in TARGETS));
  if (unknown.length > 0) {
    fail(
      `unknown target ${unknown.join(", ")}; known: ${Object.keys(TARGETS).join(", ")}`,
    );
  }
  const list = [...new Set(assets)].map((asset) => ({
    asset,
    ...TARGETS[asset],
  }));
  console.log(JSON.stringify(list));
};

const platform = (stage, asset, version) => {
  const target = TARGETS[asset] ?? fail(`unknown target ${asset}`);
  const main = readJson("package.json");
  const entries = fs
    .readdirSync(stage)
    .filter((name) => name !== "package.json");
  if (!entries.includes("bin")) {
    fail(`${stage} has no bin/; stage the binary before packaging it`);
  }
  // No `bin` here: the command belongs to the main package's launcher, the
  // one thing that knows which platform's binary to run.
  writeJson(path.join(stage, "package.json"), {
    name: `${main.name}-${asset}`,
    version,
    description: `The ${main.name} binary for ${target.os} on ${target.cpu}`,
    license: main.license,
    os: [target.os],
    cpu: [target.cpu],
    exports: { "./package.json": "./package.json" },
    // Listed by name so a dot-directory the program reads beside its binary
    // (vector's `.z3/`) is packed like any other.
    files: entries,
    repository: main.repository,
    homepage: main.homepage,
  });
};

/**
 * The launcher npm links as the command. It resolves the platform package
 * through node's own module resolution, so it works wherever npm put it, and
 * runs the binary by its absolute path, which is also what lets a binary find
 * files beside itself through `argv[0]` on systems without `/proc/self/exe`.
 */
const launcher = (name, bin) => `#!/usr/bin/env node
// Generated by nish-release: runs the prebuilt ${bin} for this platform.
import { spawnSync } from "node:child_process"
import { existsSync } from "node:fs"
import { createRequire } from "node:module"
import { dirname, join } from "node:path"

const ASSETS = ${JSON.stringify(Object.fromEntries(Object.entries(TARGETS).map(([a, t]) => [`${t.os}-${t.cpu}`, a])))}
const asset = ASSETS[\`\${process.platform}-\${process.arch}\`]
const refuse = (why) => {
  process.stderr.write(\`${bin}: \${why}\\n\`)
  process.exit(2)
}
if (asset === undefined) {
  refuse(\`no prebuilt binary for \${process.platform}/\${process.arch}; one is published for \${Object.values(ASSETS).join(", ")}\`)
}
const pkg = \`${name}-\${asset}\`
let binary = null
try {
  binary = join(dirname(createRequire(import.meta.url).resolve(\`\${pkg}/package.json\`)), "bin", ${JSON.stringify(bin)})
} catch {}
if (binary === null || !existsSync(binary)) {
  refuse(\`\${pkg} is not installed. npm installs it for this platform unless optional dependencies were skipped (--omit=optional); reinstall ${name}\`)
}
const result = spawnSync(binary, process.argv.slice(2), { stdio: "inherit" })
if (result.error) {
  refuse(\`could not run \${binary}: \${result.error.message}\`)
}
if (result.signal) {
  process.kill(process.pid, result.signal)
}
process.exit(result.status ?? 1)
`;

const main = (out, bin, version, assets) => {
  if (!/^[a-z0-9][a-z0-9._-]*$/.test(bin)) {
    fail(`bin "${bin}" is not a command name`);
  }
  const manifest = readJson("package.json");
  if (manifest.version !== version) {
    fail(`package.json's version is ${manifest.version}, not ${version}`);
  }
  if (manifest.optionalDependencies !== undefined) {
    fail(
      "package.json already declares optionalDependencies; the release writes the platform pins itself",
    );
  }
  if (manifest.bin !== undefined) {
    fail(
      "package.json already declares bin; the release writes the launcher itself",
    );
  }
  for (const asset of assets) {
    if (!(asset in TARGETS)) {
      fail(`unknown target ${asset}`);
    }
  }
  fs.mkdirSync(out, { recursive: true });
  const work = fs.mkdtempSync(path.join(os.tmpdir(), "nish-release-"));

  // Pack the repository as it is, so `files` and .npmignore decide what ships
  // exactly as they would for a plain `npm publish`; then unpack it, add the
  // launcher and the pins, and pack that.
  const plain = npmPack(".", work);
  run("tar", ["-xzf", plain, "-C", work]);
  const dir = path.join(work, "package");
  const launcherPath = `bin/${bin}.mjs`;
  if (fs.existsSync(path.join(dir, launcherPath))) {
    fail(`the package already ships ${launcherPath}`);
  }
  fs.mkdirSync(path.join(dir, "bin"), { recursive: true });
  fs.writeFileSync(path.join(dir, launcherPath), launcher(manifest.name, bin), {
    mode: 0o755,
  });

  const packed = readJson(path.join(dir, "package.json"));
  // `private` keeps an accidental `npm publish` from the checkout out of the
  // registry; the release is the deliberate one.
  packed.private = undefined;
  packed.bin = { [bin]: launcherPath };
  if (Array.isArray(packed.files)) {
    packed.files = [...packed.files, launcherPath];
  }
  packed.optionalDependencies = Object.fromEntries(
    [...new Set(assets)]
      .sort()
      .map((asset) => [`${manifest.name}-${asset}`, version]),
  );
  writeJson(path.join(dir, "package.json"), packed);
  console.log(npmPack(dir, path.resolve(out)));
  fs.rmSync(work, { recursive: true, force: true });
};

const [command, ...args] = process.argv.slice(2);
if (command === "rows" && args.length === 1) {
  rows(args[0]);
} else if (command === "platform" && args.length === 3) {
  platform(...args);
} else if (command === "main" && args.length >= 4) {
  const [out, bin, version, ...assets] = args;
  main(out, bin, version, assets);
} else {
  console.error(
    "usage: release.mjs rows <targets-json>\n" +
      "       release.mjs platform <stage-dir> <asset> <version>\n" +
      "       release.mjs main <out-dir> <bin> <version> <asset>...",
  );
  process.exit(2);
}
